export function classify(n: number): string {
  if (n === 1) {
    return "v1";
  }
  if (n === 2) {
    return "v2";
  }
  if (n === 3) {
    return "v3";
  }
  if (n === 4) {
    return "v4";
  }
  if (n === 5) {
    return "v5";
  }
  if (n === 6) {
    return "v6";
  }
  if (n === 7) {
    return "v7";
  }
  if (n === 8) {
    return "v8";
  }
  if (n === 9) {
    return "v9";
  }
  if (n === 10) {
    return "v10";
  }
  if (n === 11) {
    return "v11";
  }
  return "other";
}
